import 'package:intl/intl.dart';
import 'package:uuid/uuid.dart';

const _uuid = Uuid();

/// uuid v4 — GENERATED BY THE PHONE. This is what makes a re-push not duplicate.
String newUuid() => _uuid.v4();

/// ISO-8601 WITH OFFSET, e.g. `2026-10-08T07:12:03.412+07:00`.
///
/// Dart's built-in `DateTime.toIso8601String()` does NOT write the offset at all
/// for local time — and the server then has to guess the zone. A project in
/// Bali (WITA) would be recorded an hour off.
String isoWithOffset(DateTime t) {
  final isLocal = t.toLocal();
  final offset = isLocal.timeZoneOffset;
  final drillMarks = offset.isNegative ? '-' : '+';
  final formatTime = offset.inHours.abs().toString().padLeft(2, '0');
  final minutes = (offset.inMinutes.abs() % 60).toString().padLeft(2, '0');
  final base = DateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS").format(isLocal);
  return '$base$drillMarks$formatTime:$minutes';
}

/// Date `yyyy-MM-dd` according to the phone's calendar.
String isoDate(DateTime t) => DateFormat('yyyy-MM-dd').format(t.toLocal());

/// Number for the server's Decimal fields — sent as TEXT, not double,
/// so that 7.1 does not arrive as 7.0999999.
String decimalText(num value, {int decimals = 2}) => value.toStringAsFixed(decimals);

/// Number from the server's JSON (may be text "7.00" or a number).
double? toDoubleOrNull(Object? v) {
  if (v == null) return null;
  if (v is num) return v.toDouble();
  return double.tryParse(v.toString());
}

int? toIntOrNull(Object? v) {
  if (v == null) return null;
  if (v is int) return v;
  if (v is num) return v.toInt();
  return int.tryParse(v.toString());
}

/// Number typed by the user: both comma AND period are accepted as the decimal separator.
double? parseNumber(String text) => double.tryParse(text.trim().replaceAll(',', '.'));

/// Koordinat yang diketik DENGAN pemisah ribuan.
///
/// `"792.345,120"` -> `792345.12`. Titik dibuang sebagai pemisah ribuan,
/// koma menjadi titik desimal.
///
/// TIDAK dapat memakai [parseNumber]: di sana titik adalah pemisah DESIMAL,
/// jadi "792.345" akan terbaca 792,345 — titik yang melenceng tujuh ratus
/// sembilan puluh satu kilometer, dan tidak ada apa pun di layar yang akan
/// menunjukkannya.
double? parseKoordinat(String text) {
  final bersih = text.trim().replaceAll('.', '').replaceAll(',', '.');
  return bersih.isEmpty ? null : double.tryParse(bersih);
}

/// "792.345,120" — koordinat untuk DIBACA.
///
/// Pemisah ribuan bukan hiasan: satu digit kelebihan pada koordinat
/// menggeser titiknya sejauh satu kilometer, dan deretan tujuh angka tanpa
/// kelompok tidak dapat diperiksa dengan mata.
String formatKoordinat(double? v, {int decimals = 3}) {
  if (v == null) return '–';
  final negatif = v < 0;
  final teks = v.abs().toStringAsFixed(decimals);
  final bagian = teks.split('.');
  final bulat = bagian.first;
  final buf = StringBuffer();
  final sisa = bulat.length % 3;
  if (sisa > 0) buf.write(bulat.substring(0, sisa));
  for (var i = sisa; i < bulat.length; i += 3) {
    if (buf.isNotEmpty) buf.write('.');
    buf.write(bulat.substring(i, i + 3));
  }
  final pecahan = bagian.length > 1 ? ',${bagian[1]}' : '';
  return '${negatif ? '-' : ''}$buf$pecahan';
}

final _timeFormat = DateFormat('HH:mm');
final _dateFormat = DateFormat('EEE, d MMM yyyy', 'id');

String formatTime(DateTime t) => _timeFormat.format(t.toLocal());
String longDate(DateTime t) => _dateFormat.format(t.toLocal());

/// "00:14:32"
String formatDuration(Duration d) {
  final j = d.inHours.toString().padLeft(2, '0');
  final m = (d.inMinutes % 60).toString().padLeft(2, '0');
  final s = (d.inSeconds % 60).toString().padLeft(2, '0');
  return '$j:$m:$s';
}

String formatMeters(double? v, {int decimals = 2}) =>
    // Non-breaking space: "1,00" and "m" never end up on two lines.
    v == null ? '–' : '${v.toStringAsFixed(decimals).replaceAll('.', ',')}\u00A0m';

/// "21,71 m³" — sepasang dengan [formatMeters]; SATUANNYA IKUT.
///
/// Ada karena ketiadaannya menimbulkan dua bug sekaligus (19 Okt 2026):
/// volume dilewatkan [formatMeters] lalu dicetak "21,71 m m³", dan
/// kedalaman ditambahi ' m' sendiri lalu menjadi "14,00 m m". Keduanya
/// lolos karena tidak ada satu tempat pun yang menyatakan bahwa satuannya
/// sudah termasuk.
String formatVolume(double? v, {int decimals = 2}) =>
    v == null ? '–' : '${v.toStringAsFixed(decimals).replaceAll('.', ',')}\u00A0m³';
